    rule = rule or {"claim": "m", "equals": "x"}
    response = client.post(
        "/v1/policies",
        json={
            "tenant_id": tenant,
            "workload_id": workload,
            "name": name,
            "rule": rule,
        },
    )
    assert response.status_code == 201, response.text
    return response.json()


